// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb.evaluation.codegen;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertThrows;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.function.Executable;

/**
 * Failure identity and resource cleanup contracts for the generated-kernel runtime helpers.
 */
class KernelRuntimeFailureControlTest {

	@Test
	void closeResourcePromotesCleanupWhenProbeCancellationCannotBeSuppressed() {
		IllegalStateException cleanup = new IllegalStateException("probe close failed");

		Throwable observed = KernelRuntime.closeResource(() -> {
			throw cleanup;
		}, KernelCancelledException.INSTANCE);

		assertSame(cleanup, observed,
				"a real cleanup failure must remain observable when the primary is a suppression-disabled singleton");
		assertEquals(0, KernelCancelledException.INSTANCE.getSuppressed().length,
				"cleanup must not mutate the shared cancellation singleton");
	}

	@Test
	void closeResourcePromotesCleanupWhenQueryCancellationCannotBeSuppressed() {
		IllegalStateException cleanup = new IllegalStateException("query close failed");

		Throwable observed = KernelRuntime.closeResource(() -> {
			throw cleanup;
		}, KernelQueryCancelledException.INSTANCE);

		assertSame(cleanup, observed,
				"a real cleanup failure must remain observable when the query cancellation is a singleton");
		assertEquals(0, KernelQueryCancelledException.INSTANCE.getSuppressed().length,
				"cleanup must not mutate the shared query cancellation singleton");
	}

	@Test
	void closeResourceKeepsPerOccurrenceAllocationRefusalWithCleanupEvidence() {
		KernelRuntime.AllocationDeniedException refusal = new KernelRuntime.AllocationDeniedException();
		IllegalStateException cleanup = new IllegalStateException("allocation close failed");

		Throwable observed = KernelRuntime.closeResource(() -> {
			throw cleanup;
		}, refusal);

		assertSame(refusal, observed,
				"an allocation refusal is an occurrence-local control and must remain available for aggregate classification");
		assertEquals(1, refusal.getSuppressed().length,
				"real cleanup evidence must remain attached to the occurrence-local allocation refusal");
		assertSame(cleanup, refusal.getSuppressed()[0]);
	}

	@Test
	void closeResourcePromotesRealCleanupInsideAControlWrapper() {
		IllegalStateException cleanup = new IllegalStateException("wrapped close failed");
		RuntimeException wrappedCleanup = new RuntimeException("wrapped probe control",
				KernelCancelledException.INSTANCE);
		wrappedCleanup.addSuppressed(cleanup);

		Throwable observed = KernelRuntime.closeResource(() -> {
			throw wrappedCleanup;
		}, KernelCancelledException.INSTANCE);

		assertSame(cleanup, observed,
				"a real cleanup nested under a control wrapper must remain the failure that escapes");
		assertEquals(0, KernelCancelledException.INSTANCE.getSuppressed().length,
				"nested cleanup handling must not mutate the shared cancellation singleton");
	}

	@Test
	void closeResourceKeepsRealPrimaryWhenCleanupIsOnlyAControl() {
		IllegalStateException primary = new IllegalStateException("evaluation failed");

		Throwable observed = KernelRuntime.closeResource(() -> {
			throw KernelCancelledException.INSTANCE;
		}, primary);

		assertSame(primary, observed, "a real evaluation error remains primary over a cooperative cleanup control");
		assertEquals(1, primary.getSuppressed().length);
		assertSame(KernelCancelledException.INSTANCE, primary.getSuppressed()[0]);
	}

	@Test
	void closeHelpersPromoteCleanupOverProbeAndQueryCancellationSingletons() {
		RuntimeException probeAfterFailure = new RuntimeException("probe kernel close failure");
		assertCleanupEscapes(() -> KernelRuntime.closeAfterFailure(closingKernel(probeAfterFailure),
				KernelCancelledException.INSTANCE), probeAfterFailure);
		RuntimeException probeCursor = new RuntimeException("probe cursor close failure");
		assertCleanupEscapes(
				() -> KernelRuntime.closeCursor(closingResource(probeCursor), KernelCancelledException.INSTANCE),
				probeCursor);
		RuntimeException probeScan = new RuntimeException("probe scan close failure");
		assertCleanupEscapes(
				() -> KernelRuntime.closeScanCursor(closingScanCursor(probeScan), KernelCancelledException.INSTANCE),
				probeScan);
		RuntimeException probePlan = new RuntimeException("probe plan close failure");
		assertCleanupEscapes(
				() -> KernelRuntime.closePlanCursor(closingPlanCursor(probePlan), KernelCancelledException.INSTANCE),
				probePlan);

		RuntimeException queryAfterFailure = new RuntimeException("query kernel close failure");
		assertCleanupEscapes(() -> KernelRuntime.closeAfterFailure(closingKernel(queryAfterFailure),
				KernelQueryCancelledException.INSTANCE), queryAfterFailure);
		RuntimeException queryCursor = new RuntimeException("query cursor close failure");
		assertCleanupEscapes(
				() -> KernelRuntime.closeCursor(closingResource(queryCursor), KernelQueryCancelledException.INSTANCE),
				queryCursor);
		RuntimeException queryScan = new RuntimeException("query scan close failure");
		assertCleanupEscapes(() -> KernelRuntime.closeScanCursor(closingScanCursor(queryScan),
				KernelQueryCancelledException.INSTANCE), queryScan);
		RuntimeException queryPlan = new RuntimeException("query plan close failure");
		assertCleanupEscapes(() -> KernelRuntime.closePlanCursor(closingPlanCursor(queryPlan),
				KernelQueryCancelledException.INSTANCE), queryPlan);
	}

	@Test
	void closeHelpersRetainCleanupForPerOccurrencePrimaryFailures() {
		RuntimeException afterFailurePrimary = new RuntimeException("kernel failure");
		RuntimeException afterFailureCleanup = new RuntimeException("kernel close failure");
		KernelRuntime.closeAfterFailure(closingKernel(afterFailureCleanup), afterFailurePrimary);
		assertSuppressed(afterFailurePrimary, afterFailureCleanup);

		RuntimeException cursorPrimary = new RuntimeException("cursor owner failure");
		RuntimeException cursorCleanup = new RuntimeException("cursor close failure");
		KernelRuntime.closeCursor(closingResource(cursorCleanup), cursorPrimary);
		assertSuppressed(cursorPrimary, cursorCleanup);

		RuntimeException scanPrimary = new RuntimeException("scan owner failure");
		RuntimeException scanCleanup = new RuntimeException("scan close failure");
		KernelRuntime.closeScanCursor(closingScanCursor(scanCleanup), scanPrimary);
		assertSuppressed(scanPrimary, scanCleanup);

		RuntimeException planPrimary = new RuntimeException("plan owner failure");
		RuntimeException planCleanup = new RuntimeException("plan close failure");
		KernelRuntime.closePlanCursor(closingPlanCursor(planCleanup), planPrimary);
		assertSuppressed(planPrimary, planCleanup);
	}

	@Test
	void closeHelpersRethrowCleanupWhenThereIsNoPrimaryFailure() {
		RuntimeException cursorCleanup = new RuntimeException("cursor close failure");
		assertSame(cursorCleanup,
				assertThrows(RuntimeException.class,
						() -> KernelRuntime.closeCursor(closingResource(cursorCleanup), null)));

		RuntimeException scanCleanup = new RuntimeException("scan close failure");
		assertSame(scanCleanup, assertThrows(RuntimeException.class,
				() -> KernelRuntime.closeScanCursor(closingScanCursor(scanCleanup), null)));

		RuntimeException planCleanup = new RuntimeException("plan close failure");
		assertSame(planCleanup, assertThrows(RuntimeException.class,
				() -> KernelRuntime.closePlanCursor(closingPlanCursor(planCleanup), null)));
	}

	private static void assertSuppressed(Throwable primary, Throwable cleanup) {
		assertEquals(1, primary.getSuppressed().length);
		assertSame(cleanup, primary.getSuppressed()[0]);
	}

	private static void assertCleanupEscapes(Executable close, RuntimeException expected) {
		assertSame(expected, assertThrows(RuntimeException.class, close));
	}

	private static JaninoKernel closingKernel(RuntimeException cleanup) {
		return new JaninoKernel() {
			@Override
			public void bind(KernelContext context) {
			}

			@Override
			public int fill(long[] rowBuffer, int maxRows) {
				return 0;
			}

			@Override
			public void close() {
				throw cleanup;
			}
		};
	}

	private static AutoCloseable closingResource(RuntimeException cleanup) {
		return () -> {
			throw cleanup;
		};
	}

	private static KernelQuadCursor closingScanCursor(RuntimeException cleanup) {
		return new KernelQuadCursor() {
			@Override
			public int fill(long[] quadBuffer, int maxRows) {
				return 0;
			}

			@Override
			public void close() {
				throw cleanup;
			}
		};
	}

	private static KernelPlan.Cursor closingPlanCursor(RuntimeException cleanup) {
		return new KernelPlan.Cursor() {
			@Override
			public int fill(long[] rowBuffer, int maxRows) {
				return 0;
			}

			@Override
			public void close() {
				throw cleanup;
			}
		};
	}
}
